{"knowledge_entries":[
  {
    "intended_agents":["agent_materialien_guide"],
    "name":"Materialien im Raum",
    "source_object_ids":["object_001","object_004","object_007","object_010","object_013"],
    "tag":"materialien",
    "text":"Im Bereich 'Kollektion 1: Stärke & Kristalle' finden sich Exponate wie Stärke-Stationen (z.B. object_001, object_007, object_013) und Kristallmodelle (object_004, object_010), die verschiedene Aspekte synthetischer Materialien und deren Struktur zeigen."
  },
  {
    "intended_agents":["agent_materialien_guide"],
    "name":"Stärke erleben",
    "source_object_ids":["object_001","object_007","object_013"],
    "tag":"st_rke",
    "text":"Die Stärke-Stationen in Kollektion 1 (object_001, object_007, object_013) ermöglichen es, die Belastbarkeit und Festigkeit unterschiedlicher Materialien interaktiv zu testen und zu vergleichen."
  },
  {
    "intended_agents":["agent_materialien_guide"],
    "name":"Kristallstrukturen",
    "source_object_ids":["object_004","object_010"],
    "tag":"kristallstrukturen",
    "text":"Kristallmodelle (object_004, object_010) in Kollektion 1 veranschaulichen den inneren Aufbau von Materialien und helfen, die Bedeutung von Kristallstrukturen für Materialeigenschaften zu verstehen."
  },
  {
    "intended_agents":["agent_materialien_guide"],
    "name":"Materialvergleich in Kollektion 1",
    "source_object_ids":["object_001","object_004","object_007","object_010","object_013"],
    "tag":"materialvergleich",
    "text":"Kollektion 1 bietet die Möglichkeit, verschiedene Materialien anhand ihrer Stärke und Kristallstruktur direkt miteinander zu vergleichen – z.B. an den interaktiven Stationen und Modellen."
  },
  {
    "intended_agents":["agent_polymer_keramik"],
    "name":"Polymere in Kollektion 2",
    "source_object_ids":["object_002","object_008","object_014"],
    "tag":"polymere",
    "text":"Polymerproben (object_002, object_008, object_014) in Kollektion 2 zeigen die Vielseitigkeit und typischen Eigenschaften von Kunststoffen, wie Flexibilität und Formbarkeit."
  },
  {
    "intended_agents":["agent_polymer_keramik"],
    "name":"Keramiken entdecken",
    "source_object_ids":["object_005","object_011"],
    "tag":"keramiken",
    "text":"Keramikexponate (object_005, object_011) in Kollektion 2 demonstrieren die Härte, Temperaturbeständigkeit und technische Anwendungsmöglichkeiten moderner Keramiken."
  },
  {
    "intended_agents":["agent_polymer_keramik"],
    "name":"Materialanalyse in Kollektion 2",
    "source_object_ids":["object_002","object_005","object_008","object_011","object_014"],
    "tag":"materialanalyse",
    "text":"In Kollektion 2 können Besucher die Unterschiede und Gemeinsamkeiten von Polymeren und Keramiken analysieren und ihre Materialeigenschaften direkt vergleichen."
  },
  {
    "intended_agents":["agent_polymer_keramik"],
    "name":"Anwendungen von Polymeren & Keramiken",
    "source_object_ids":["object_002","object_005","object_008","object_011","object_014"],
    "tag":"anwendungen",
    "text":"Die Exponate in Kollektion 2 verdeutlichen typische Einsatzgebiete von Polymeren (z.B. Verpackungen, Alltagsprodukte) und Keramiken (z.B. technische Bauteile, Isolatoren)."
  },
  {
    "intended_agents":["agent_faser_metall"],
    "name":"Fasern in Kollektion 3",
    "source_object_ids":["object_003","object_009","object_015"],
    "tag":"fasern",
    "text":"Faserdisplays (object_003, object_009, object_015) in Kollektion 3 illustrieren Aufbau und Eigenschaften von synthetischen und technischen Fasern, etwa ihre Zugfestigkeit und Einsatzbereiche."
  },
  {
    "intended_agents":["agent_faser_metall"],
    "name":"Metalle in Kollektion 3",
    "source_object_ids":["object_006","object_012"],
    "tag":"metalle",
    "text":"Metallproben (object_006, object_012) in Kollektion 3 zeigen typische Merkmale wie Leitfähigkeit, Verformbarkeit und Festigkeit, die Metalle für viele Anwendungen qualifizieren."
  },
  {
    "intended_agents":["agent_faser_metall"],
    "name":"Strukturvergleich Fasern & Metalle",
    "source_object_ids":["object_003","object_006","object_009","object_012","object_015"],
    "tag":"strukturvergleich",
    "text":"Kollektion 3 ermöglicht den direkten Vergleich von Fasern und Metallen hinsichtlich ihrer inneren Struktur und der daraus resultierenden Materialeigenschaften."
  },
  {
    "intended_agents":["agent_faser_metall"],
    "name":"Anwendungsbeispiele für Fasern & Metalle",
    "source_object_ids":["object_003","object_006","object_009","object_012","object_015"],
    "tag":"anwendungsbeispiele",
    "text":"Die Exponate in Kollektion 3 zeigen konkrete Beispiele, wie Fasern (z.B. in Textilien) und Metalle (z.B. in Konstruktionen) in Technik und Alltag eingesetzt werden."
  }
]}
